#endif

#include "fuzzer_reader.h"
#include "libopensc/pkcs15.h"
#include "libopensc/internal.h"

uint16_t fuzz_get_buffer(const uint8_t **buf, size_t buf_len, const uint8_t **out, size_t *out_len)
{
	uint16_t len = 0;

	if (!buf || !(*buf) || buf_len < 2)
		return 0;

	/* Get length of the result buffer*/
	len = *((uint16_t *) *buf);
	if (buf_len - 2 <= len)
		return 0;
	(*buf) += 2;
	buf_len -= 2;

	/* Set out buffer to new reader data*/
	*out = *buf + len;
	*out_len = buf_len - len;
	return len;
}

int LLVMFuzzerTestOneInput(const uint8_t *Data, size_t Size)
{
	size_t i = 0;
	struct sc_reader *reader = NULL;
	const uint8_t *buf = Data, *reader_data = NULL;
	uint16_t buf_len = 0;
	size_t reader_data_len = 0;
	struct sc_context *ctx = NULL;
	struct sc_pkcs15_card *p15card = NULL;
	sc_card_t *card = NULL;
	struct sc_pkcs15_tokeninfo *tokeninfo = NULL;
	int (* decode_entries[])(struct sc_pkcs15_card *, struct sc_pkcs15_object *,
			const u8 **nbuf, size_t *nbufsize) = {
		sc_pkcs15_decode_prkdf_entry, sc_pkcs15_decode_pukdf_entry,
		sc_pkcs15_decode_skdf_entry, sc_pkcs15_decode_cdf_entry,
		sc_pkcs15_decode_dodf_entry, sc_pkcs15_decode_aodf_entry
	};
	int algorithms[] = { SC_ALGORITHM_RSA, SC_ALGORITHM_EC, SC_ALGORITHM_GOSTR3410, SC_ALGORITHM_EDDSA };

	/* Split data into testing buffer and APDU for connecting */
	if ((buf_len = fuzz_get_buffer(&buf, Size, &reader_data, &reader_data_len)) == 0)
		return 0;

	/* Establish context for fuzz app*/
	sc_establish_context(&ctx, "fuzz");
	if (!ctx)
		return 0;

	if (fuzz_connect_card(ctx, &card, &reader, reader_data, reader_data_len) != SC_SUCCESS)
		goto err;

	sc_pkcs15_bind(card, NULL, &p15card);
	if (!p15card)
		goto err;

	for (i = 0; i < sizeof decode_entries/sizeof *decode_entries; i++) {
		struct sc_pkcs15_object *obj;
		const u8 *p = buf;
		size_t len = (size_t) buf_len;
		if (!(obj = calloc(1, sizeof *obj)))
			goto err;
		while (SC_SUCCESS == decode_entries[i](p15card, obj, &p, &len)) {
			sc_pkcs15_free_object(obj);
			if (!(obj = calloc(1, sizeof *obj)))
				goto err;
		}
		sc_pkcs15_free_object(obj);
	}

	for (i = 0; i < 4; i++) {
		struct sc_pkcs15_pubkey *pubkey = calloc(1, sizeof *pubkey);
		if (!pubkey)
			goto err;
		pubkey->algorithm = algorithms[i];
		sc_pkcs15_decode_pubkey(ctx, pubkey, buf, buf_len);
		sc_pkcs15_free_pubkey(pubkey);
	}

	tokeninfo = sc_pkcs15_tokeninfo_new();
	sc_pkcs15_parse_tokeninfo(ctx, tokeninfo, buf, buf_len);
	sc_pkcs15_free_tokeninfo(tokeninfo);

	sc_pkcs15_parse_unusedspace(buf, buf_len, p15card);

err:
	sc_pkcs15_card_free(p15card);
	sc_disconnect_card(card);
	sc_release_context(ctx);
	return 0;
}

	if (card->cache.valid) {
		sc_file_free(card->cache.current_ef);
	}
	card->cache.current_ef = NULL;

	sc_file_dup(&card->cache.current_df, mf_file);
	card->cache.valid = 1;

	if (file_out && *file_out == NULL)
		*file_out = mf_file;
	else
		sc_file_free(mf_file);

	LOG_FUNC_RETURN(ctx, rv);
}


static int
iasecc_select_aid(struct sc_card *card, struct sc_aid *aid, unsigned char *out, size_t *out_len)
{
	struct sc_apdu apdu;
	unsigned char apdu_resp[SC_MAX_APDU_BUFFER_SIZE];
	int rv;

	LOG_FUNC_CALLED(card->ctx);

	/* Select application (deselect previously selected application) */
	sc_format_apdu(card, &apdu, SC_APDU_CASE_4_SHORT, 0xA4, 0x04, 0x00);
	apdu.lc = aid->len;
	apdu.data = aid->value;
	apdu.datalen = aid->len;
	apdu.resplen = sizeof(apdu_resp);
	apdu.resp = apdu_resp;

	rv = sc_transmit_apdu(card, &apdu);
	LOG_TEST_RET(card->ctx, rv, "APDU transmit failed");
	rv = sc_check_sw(card, apdu.sw1, apdu.sw2);
	LOG_TEST_RET(card->ctx, rv, "Cannot select AID");

	if (*out_len < apdu.resplen)
		LOG_TEST_RET(card->ctx, SC_ERROR_BUFFER_TOO_SMALL, "Cannot select AID");
	memcpy(out, apdu.resp, apdu.resplen);

	LOG_FUNC_RETURN(card->ctx, SC_SUCCESS);
}


static int
iasecc_match_card(struct sc_card *card)
{
	struct sc_context *ctx = card->ctx;
	int i;

	i = _sc_match_atr(card, iasecc_known_atrs, &card->type);
	if (i < 0)   {
		sc_log(ctx, "card not matched");
		return 0;
	}

	sc_log(ctx, "'%s' card matched", iasecc_known_atrs[i].name);

	LOG_FUNC_RETURN(ctx, rv);
}


static int
iasecc_check_sw(struct sc_card *card, unsigned int sw1, unsigned int sw2)
{
	if (sw1 == 0x62 && sw2 == 0x82)
		return SC_SUCCESS;

	return iso_ops->check_sw(card, sw1, sw2);
}


static unsigned
iasecc_get_algorithm(struct sc_context *ctx, const struct sc_security_env *env,
		unsigned operation, unsigned mechanism)
{
    const struct sc_supported_algo_info *info = NULL;
    int ii;

    if (!env)
        return 0;

    for (ii=0;ii<SC_MAX_SUPPORTED_ALGORITHMS && env->supported_algos[ii].reference; ii++)
        if ((env->supported_algos[ii].operations & operation)
			&& (env->supported_algos[ii].mechanism == mechanism))
            break;

    if (ii < SC_MAX_SUPPORTED_ALGORITHMS && env->supported_algos[ii].reference)   {
        info = &env->supported_algos[ii];
        sc_log(ctx, "found IAS/ECC algorithm %X:%X:%X:%X",
			info->reference, info->mechanism, info->operations, info->algo_ref);
    }
    else   {
        sc_log(ctx, "cannot find IAS/ECC algorithm (operation:%X,mechanism:%X)", operation, mechanism);
    }

    return info ? info->algo_ref : 0;
}


static int
iasecc_se_cache_info(struct sc_card *card, struct iasecc_se_info *se)
{
	struct iasecc_private_data *prv = (struct iasecc_private_data *) card->drv_data;
	struct sc_context *ctx = card->ctx;
